#include <iostream>
#include <cstring>
#include <pcre.h>

bool matchRegex(pcre* re, const char* subject) {
    if (re == nullptr || subject == nullptr) {
        std::cerr << "Invalid input: null pointer provided." << std::endl;
        return false;
    }

    int subjectLength = strlen(subject);
    int ovector[30];  // This array will store captured substring positions

    int rc = pcre_exec(re, NULL, subject, subjectLength, 0, 0, ovector, 30);
    if (rc >= 0) {
        std::cout << "Match found!" << std::endl;
        return true;
    } else if (rc == PCRE_ERROR_NOMATCH) {
        std::cout << "No match found." << std::endl;
    } else if (rc == PCRE_ERROR_NOSUBJECT) {
        std::cerr << "Regex matching error: No subject provided." << std::endl;
    } else if (rc == PCRE_ERROR_NOMATCH) {
        std::cout << "No match found." << std::endl;
    } else if (rc == PCRE_ERROR_BADPAT) {
        std::cerr << "Regex matching error: Invalid pattern." << std::endl;
    } else if (rc == PCRE_ERROR_UNKNOWN_OPTION) {
        std::cerr << "Regex matching error: Unknown option." << std::endl;
    } else if (rc == PCRE_ERROR_MATCHLIMIT) {
        std::cerr << "Regex matching error: Match limit exceeded." << std::endl;
    } else if (rc == PCRE_ERROR_RECURSIONLIMIT) {
        std::cerr << "Regex matching error: Recursion limit exceeded." << std::endl;
    } else {
        std::cerr << "Regex matching error: " << rc << std::endl;
    }
    return false;
}
